import json

def solve(xs):
    if len(xs) < 2:
        return len(xs)
    up = 1
    down = 1
    for i in range(1, len(xs)):
        if xs[i] > xs[i-1]:
            up = down + 1
        elif xs[i] < xs[i-1]:
            down = up + 1
    return max(up, down)

with open('tests/expected.json') as f:
    data = json.load(f)

for key, expected in data['cases'].items():
    xs = eval(key)
    result = solve(xs)
    status = 'OK' if result == expected else 'FAIL'
    print(f'{status}: {xs} -> {result} (expected {expected})')

def solve(xs: list[int]) -> int:
    """Return the length of the longest run of consecutive elements
    that all share the same parity (all even or all odd).
    A single element counts as a run of length 1; empty input -> 0."""
    if not xs:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(xs)):
        if (xs[i] % 2) == (xs[i - 1] % 2):
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    return best

